package generate

import (
	"bytes"
	"fmt"
	"os"
	"path"
	"path/filepath"
	"strings"
)

var generatedPrefix = []byte("// Code generated by cmd/tlgen (")

type stagedFile struct {
	target string
	temp   string
}

// Write atomically replaces changed outputs and removes stale generated files.
func Write(root string, outputs []Output) (err error) {
	if root == "" {
		return fmt.Errorf("empty output root")
	}
	expected := make(map[string]struct{}, len(outputs))
	staged := make([]stagedFile, 0, len(outputs))
	defer func() {
		for _, file := range staged {
			_ = os.Remove(file.temp)
		}
	}()

	for _, output := range outputs {
		if err := validateOutputPath(output.Path); err != nil {
			return err
		}
		if _, exists := expected[output.Path]; exists {
			return fmt.Errorf("duplicate output path %q", output.Path)
		}
		expected[output.Path] = struct{}{}

		target := filepath.Join(root, filepath.FromSlash(output.Path))
		current, readErr := os.ReadFile(target)
		if readErr == nil && bytes.Equal(current, output.Data) {
			continue
		}
		if readErr == nil && !bytes.HasPrefix(current, generatedPrefix) {
			return fmt.Errorf("refuse to overwrite non-generated file %q", output.Path)
		}
		if readErr != nil && !os.IsNotExist(readErr) {
			return fmt.Errorf("read %q: %w", output.Path, readErr)
		}
		if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
			return fmt.Errorf("create directory for %q: %w", output.Path, err)
		}
		temp, err := os.CreateTemp(filepath.Dir(target), ".tlgen-*")
		if err != nil {
			return fmt.Errorf("create temporary file for %q: %w", output.Path, err)
		}
		tempName := temp.Name()
		if err := temp.Chmod(0o644); err != nil {
			_ = temp.Close()
			_ = os.Remove(tempName)
			return fmt.Errorf("set mode for %q: %w", output.Path, err)
		}
		if _, err := temp.Write(output.Data); err != nil {
			_ = temp.Close()
			_ = os.Remove(tempName)
			return fmt.Errorf("write temporary file for %q: %w", output.Path, err)
		}
		if err := temp.Close(); err != nil {
			_ = os.Remove(tempName)
			return fmt.Errorf("close temporary file for %q: %w", output.Path, err)
		}
		staged = append(staged, stagedFile{target: target, temp: tempName})
	}

	for index := range staged {
		file := &staged[index]
		if err := os.Rename(file.temp, file.target); err != nil {
			return fmt.Errorf("replace %q: %w", file.target, err)
		}
		file.temp = ""
	}
	return removeStale(root, expected)
}

func validateOutputPath(value string) error {
	if value != path.Clean(value) ||
		path.Dir(value) != "tl" ||
		!isGeneratedName(path.Base(value)) {
		return fmt.Errorf("unsafe generated output path %q", value)
	}
	return nil
}

func isGeneratedName(name string) bool {
	if name == "api.go" || name == "mtp.go" {
		return true
	}
	var suffix string
	switch {
	case strings.HasPrefix(name, "api_"):
		suffix = strings.TrimPrefix(name, "api_")
	case strings.HasPrefix(name, "mtp_"):
		suffix = strings.TrimPrefix(name, "mtp_")
	default:
		return false
	}
	if !strings.HasSuffix(suffix, ".go") {
		return false
	}
	suffix = strings.TrimSuffix(suffix, ".go")
	if suffix == "" {
		return false
	}
	for _, current := range suffix {
		if current == '_' ||
			current >= 'a' && current <= 'z' ||
			current >= '0' && current <= '9' {
			continue
		}
		return false
	}
	return true
}

func removeStale(root string, expected map[string]struct{}) error {
	directory := filepath.Join(root, "tl")
	entries, err := os.ReadDir(directory)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return fmt.Errorf("list generated directory: %w", err)
	}
	for _, entry := range entries {
		if entry.IsDir() || filepath.Ext(entry.Name()) != ".go" {
			continue
		}
		slashPath := path.Join("tl", entry.Name())
		if _, exists := expected[slashPath]; exists {
			continue
		}
		match := filepath.Join(directory, entry.Name())
		data, err := os.ReadFile(match)
		if err != nil {
			return fmt.Errorf("read stale candidate %q: %w", slashPath, err)
		}
		if !bytes.HasPrefix(data, generatedPrefix) {
			continue
		}
		if err := os.Remove(match); err != nil {
			return fmt.Errorf("remove stale generated file %q: %w", slashPath, err)
		}
	}
	return nil
}
